create or replace function public.business_growth_analytics(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ with ci as(select ci.id,ci.user_id from check_ins ci join locations l on l.id=ci.location_id where l.business_id=p_business_id and ci.checked_in_at between p_start and p_end),rv as(select r.id from reviews r join locations l on l.id=r.location_id where l.business_id=p_business_id and r.created_at between p_start and p_end and r.status<>'hidden'),loc as(select count(*) locations,count(*) filter(where is_active) active_locations from locations where business_id=p_business_id) select jsonb_build_object('check_ins',(select count(*) from ci),'unique_users',(select count(distinct user_id) from ci),'reviews',(select count(*) from rv),'new_users',(select count(distinct ci.user_id) from ci join profiles p on p.id=ci.user_id where p.created_at between p_start and p_end),'locations',(select locations from loc),'active_locations',(select active_locations from loc)); $$;
create or replace function public.business_rewards_analytics(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ with c as(select ci.id,coalesce(ci.points_awarded,0) points_awarded from check_ins ci join locations l on l.id=ci.location_id where l.business_id=p_business_id and ci.checked_in_at between p_start and p_end),pts as(select pt.id,pt.points from point_transactions pt where pt.created_at between p_start and p_end and(pt.reason ilike '%check%' or pt.reference_id in(select id from c))) select jsonb_build_object('check_ins',(select count(*) from c),'points_awarded',(select coalesce(sum(points_awarded),0) from c),'reward_events',(select count(*) from pts),'reward_points',(select coalesce(sum(points),0) from pts)); $$;
create or replace function public.business_promotion_analytics(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ with p as(select id,active from promotions where business_id=p_business_id),ev as(select ae.promotion_id,ae.event_type,ae.user_id from analytics_events ae join p on p.id=ae.promotion_id where ae.created_at between p_start and p_end) select jsonb_build_object('business_id',p_business_id,'promotions',(select count(*) from p),'active_promotions',(select count(*) from p where active),'promotion_views',(select count(*) from ev where event_type='promotion_view'),'redemptions',(select count(*) from ev where event_type='promotion_redeemed'),'unique_redeemers',(select count(distinct user_id) from ev where event_type='promotion_redeemed'),'conversion_rate_pct',case when (select count(*) from ev where event_type='promotion_view')=0 then 0 else round((100.0*(select count(*) from ev where event_type='promotion_redeemed')/(select count(*) from ev where event_type='promotion_view'))::numeric,2) end); $$;
create or replace function public.business_event_analytics(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ with ev as(select id from business_events where business_id=p_business_id and(event_date is null or event_date between p_start::date and p_end::date)),rs as(select count(distinct er.user_id) n from event_rsvps er where er.event_id in(select id from ev)),ae as(select count(*) filter(where event_type='location_view') views,count(*) filter(where event_type='event_rsvp') tracked_rsvps from analytics_events where event_id in(select id from ev) and created_at between p_start and p_end) select jsonb_build_object('events',(select count(*) from ev),'rsvps',(select n from rs),'event_views',(select views from ae),'event_rsvps_tracked',(select tracked_rsvps from ae)); $$;
create or replace function public.business_occupancy_analytics(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ with v as(select lv.occurred_at,lv.user_id from location_visits lv join locations l on l.id=lv.location_id where l.business_id=p_business_id and lv.occurred_at between p_start and p_end),c as(select ci.checked_in_at occurred_at,ci.user_id from check_ins ci join locations l on l.id=ci.location_id where l.business_id=p_business_id and ci.checked_in_at between p_start and p_end),allv as(select * from v union all select * from c),peak as(select extract(hour from occurred_at)::int h,count(*) n from allv group by 1 order by n desc limit 1) select jsonb_build_object('visits',(select count(*) from v),'check_ins',(select count(*) from c),'unique_visitors',(select count(distinct user_id) from allv),'peak_hour',(select h from peak)); $$;
